{
  "doc_type": "Avviso",
  "audience": "Studenti di quarta media e i loro genitori",
  "core": {
    "what": {
      "text": "Settimana di stage di orientamento per tutte le classi di quarta media.",
      "segment_ids": ["s0003"]
    },
    "must_do": {
      "text": "Cercare autonomamente un posto di stage, consegnare l'attestato firmato entro il 19‑02‑2027 e consegnare il rapporto di stage entro il 02‑04‑2027.",
      "segment_ids": ["s0007", "s0008", "s0021"]
    },
    "deadline": {
      "text": "L'attestato deve essere consegnato entro il 19‑02‑2027.",
      "segment_ids": ["s0008"]
    },
    "cost": {
      "text": "Rimborso massimo di 30 CHF alla settimana per i trasporti pubblici.",
      "segment_ids": ["s0017"]
    },
    "contact": {
      "text": "Docente di classe, segreteria (tel. 0911234570, email segreteria@sm-esempiopoli.example) e Ufficio orientamento (Via della Stazione 10, 6899 Esempiopoli).",
      "segment_ids": ["s0008", "s0010", "s0013", "s0023"]
    }
  },
  "facts": [
    {
      "id": "f01",
      "kind": "deadline",
      "text": "L'attestato compilato e firmato deve essere consegnato entro il 19‑02‑2027.",
      "value_norm": "2027-02-19",
      "segment_ids": ["s0008"],
      "must_keep": true
    },
    {
      "id": "f02",
      "kind": "deadline",
      "text": "Se non si ha ancora un posto di stage entro il 05‑02‑2027, bisogna informare il docente.",
      "value_norm": "2027-02-05",
      "segment_ids": ["s0009"],
      "must_keep": true
    },
    {
      "id": "f03",
      "kind": "deadline",
      "text": "Il rapporto di stage deve essere consegnato entro il 02‑04‑2027.",
      "value_norm": "2027-04-02",
      "segment_ids": ["s0021"],
      "must_keep": true
    },
    {
      "id": "f04",
      "kind": "amount",
      "text": "La scuola rimborsa al massimo 30 CHF alla settimana per i trasporti pubblici.",
      "value_norm": "30",
      "segment_ids": ["s0017"],
      "must_keep": true
    },
    {
      "id": "f05",
      "kind": "obligation",
      "text": "La partecipazione alla settimana di stage è obbligatoria per tutti gli studenti.",
      "value_norm": null,
      "segment_ids": ["s0006"],
      "must_keep": true
    },
    {
      "id": "f06",
      "kind": "obligation",
      "text": "Il posto di stage va cercato in modo autonomo dallo studente.",
      "value_norm": null,
      "segment_ids": ["s0007"],
      "must_keep": true
    },
    {
      "id": "f07",
      "kind": "condition",
      "text": "L'orario di lavoro giornaliero non supera le 8 ore.",
      "value_norm": null,
      "segment_ids": ["s0012"],
      "must_keep": false
    },
    {
      "id": "f08",
      "kind": "contact",
      "text": "Telefono della segreteria: 0911234570.",
      "value_norm": "0911234570",
      "segment_ids": ["s0013"],
      "must_keep": true
    },
    {
      "id": "f09",
      "kind": "contact",
      "text": "Email della segreteria: segreteria@sm-esempiopoli.example.",
      "value_norm": "segreteria@sm-esempiopoli.example",
      "segment_ids": ["s0023"],
      "must_keep": true
    },
    {
      "id": "f10",
      "kind": "contact",
      "text": "Indirizzo dell'Ufficio orientamento: Via della Stazione 10, 6899 Esempiopoli.",
      "value_norm": null,
      "segment_ids": ["s0010"],
      "must_keep": true
    }
  ],
  "hard_terms": [
    {
      "term": "Ufficio dell'orientamento scolastico e professionale",
      "explanation": "Ufficio della scuola che aiuta gli studenti a trovare un posto di stage. È aperto dal lunedì al giovedì, dalle 13:30 alle 17:30.",
      "segment_ids": ["s0010"]
    },
    {
      "term": "attestato",
      "explanation": "Documento firmato dall'azienda che conferma il periodo di stage. Deve essere consegnato al docente.",
      "segment_ids": ["s0008"]
    },
    {
      "term": "diario di stage",
      "explanation": "Quaderno dove lo studente annota le attività svolte durante lo stage. Fa parte del dossier di orientamento.",
      "segment_ids": ["s0020"]
    },
    {
      "term": "pagella",
      "explanation": "Documento che riporta i voti e le assenze dello studente. Le assenze non giustificate vengono segnate qui.",
      "segment_ids": ["s0015"]
    },
    {
      "term": "CHF",
      "explanation": "Abbreviazione del franco svizzero, la moneta della Svizzera. È usata per indicare il rimborso dei trasporti.",
      "segment_ids": ["s0017"]
    },
    {
      "term": "assicurazione di responsabilità civile",
      "explanation": "Copertura assicurativa per danni a terzi. In questo caso è a carico dei genitori.",
      "segment_ids": ["s0019"]
    }
  ],
  "omit_candidates": [
    {
      "segment_ids": ["s0011"],
      "reason": "Informazione sugli orari aziendali, non essenziale per la comprensione dell'obbligo."
    },
    {
      "segment_ids": ["s0015"],
      "reason": "Dettaglio sulla pagella, non necessario per l'esecuzione dello stage."
    },
    {
      "segment_ids": ["s0018"],
      "reason": "Indicazione dell'assicurazione scuola, informazione di contesto."
    },
    {
      "segment_ids": ["s0019"],
      "reason": "Dettaglio sull'assicurazione dei genitori, non richiesto per l'azione immediata."
    }
  ]
}

